import{PARTS,THEMES,layer,presets,renderEffect}from './engine.js?perf=2';
import{exportEffect}from './export.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let catalogue=presets(),state={version:1,name:'Arcane awakening',duration:2,layers:structuredClone(catalogue[0].layers)},selected=state.layers[0].id,playing=true,time=.5,zoom=1,showGrid=true,bg=0,libraryTab='presets',activePreset=0,format='png',undo=[],redo=[],lastStamp=0,saveTimer;
const canvas=$('#preview'),ctx=canvas.getContext('2d',{alpha:false});
const timecode=$('#timecode'),scrub=$('#scrub'),fpsLabel=$('#fps');
const timeText=document.createTextNode(''),durationText=el('small');timecode.replaceChildren(timeText,durationText);
const gridCanvas=document.createElement('canvas'),gridCtx=gridCanvas.getContext('2d',{alpha:false});
let dirty=true,renderPending=false,lastFrame=0,lastUI=0,cssWidth=1,gridKey='',fpsStart=0,fpsFrames=0;
const previewOptions={preview:true};
function invalidate(){dirty=true;if(!renderPending){renderPending=true;requestAnimationFrame(draw);}}
document.addEventListener('input',invalidate);document.addEventListener('click',invalidate);document.addEventListener('keydown',invalidate);
document.addEventListener('visibilitychange',()=>{lastStamp=0;lastFrame=0;invalidate();});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('close',()=>{lastStamp=0;invalidate();});
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function checkpoint(){undo.push(JSON.stringify(state));if(undo.length>40)undo.shift();redo=[];}
function persist(){invalidate();clearTimeout(saveTimer);$('#saveStatus').textContent='● Saving…';saveTimer=setTimeout(()=>{try{localStorage.setItem('vfx-forge-project',JSON.stringify(state));$('#saveStatus').textContent='● Saved locally';}catch{$('#saveStatus').textContent='● Storage unavailable';}},300);}
function setText(el,t){el.textContent=t;return el;}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function current(){return state.layers.find(l=>l.id===selected);}
function changeDone(){persist();renderTimeline();}
function refresh(){if(!current())selected=state.layers[0]?.id;$('#rename').textContent=state.name+' ⌄';$('#effectTitle').textContent=state.name;$('#duration').value=state.duration;$('#scrub').max=state.duration;renderLayers();renderProperties();renderTimeline();persist();}
function applyPreset(i){checkpoint();activePreset=i;let p=catalogue[i];state={version:1,name:p.name,duration:2,layers:structuredClone(p.layers)};if(p.theme){for(let l of state.layers){l.color=THEMES[p.theme][1];l.accent=THEMES[p.theme][2];}}selected=state.layers[0].id;time=0;refresh();renderLibrary();toast('โหลด '+p.name);}
function renderLibrary(){const container=$('#library');container.replaceChildren();let query=$('#search').value.toLowerCase();$('#libraryLabel').textContent=libraryTab==='presets'?'START WITH A LITTLE MAGIC':'BUILD YOUR OWN EFFECT';const items=libraryTab==='presets'?catalogue:PARTS;items.forEach((p,i)=>{if(!(p.name+' '+(p.th||'')).toLowerCase().includes(query))return;let b=el('button','preset-card'+(libraryTab==='presets'&&activePreset===i?' selected':''));const thumb=el('canvas');thumb.width=220;thumb.height=170;let ls=libraryTab==='presets'?p.layers:[layer(p.type)];if(libraryTab==='presets'&&p.theme){ls=structuredClone(ls);ls.forEach(l=>{l.color=THEMES[p.theme][1];l.accent=THEMES[p.theme][2];});}renderEffect(thumb,ls,.65,2,{zoom:1.1,preview:true});b.append(thumb,el('span','card-label',p.name),el('small','',p.tag||p.th));b.onclick=()=>libraryTab==='presets'?applyPreset(i):add(p.type);container.append(b);});if(!container.children.length)container.append(el('p','empty','ไม่พบเอฟเฟกต์'));}
function add(type){if(state.layers.length>=12)return toast('รองรับสูงสุด 12 เลเยอร์ต่อเอฟเฟกต์');checkpoint();let l=layer(type,{length:state.duration});state.layers.push(l);selected=l.id;refresh();toast('เพิ่ม '+l.name);}
function renderLayers(){const list=$('#layers');list.replaceChildren();[...state.layers].reverse().forEach(l=>{const row=el('div','layer'+(l.id===selected?' selected':'')+(!l.visible?' hidden':''));row.tabIndex=0;row.setAttribute('role','button');row.setAttribute('aria-label','เลือก '+l.name);row.style.setProperty('--layer-color',l.color);row.onclick=()=>{selected=l.id;renderLayers();renderProperties();};row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();row.click();}};const p=PARTS.find(p=>p.type===l.type);let info=el('div','layer-info');info.append(el('strong','',l.name),el('small','',p.th));let toggle=el('button','',l.visible?'◉':'○');toggle.title=l.visible?'ซ่อนเลเยอร์':'แสดงเลเยอร์';toggle.setAttribute('aria-label',toggle.title+' '+l.name);toggle.onclick=e=>{e.stopPropagation();checkpoint();l.visible=!l.visible;refresh();};row.append(el('span','layer-symbol',p.icon),info,toggle);list.append(row);});if(!state.layers.length)list.append(el('div','empty','เพิ่มเลเยอร์เพื่อเริ่มสร้างเอฟเฟกต์'));}
function range(container,l,key,label,min,max,step,unit=''){let row=el('div','prop'),lab=el('label','',label),out=el('output','',Number(l[key]).toFixed(step<1?2:0)+unit),input=el('input');input.type='range';input.min=min;input.max=max;input.step=step;input.value=l[key];input.setAttribute('aria-label',label);lab.append(out);input.addEventListener('pointerdown',()=>checkpoint());input.addEventListener('keydown',e=>{if(e.key.startsWith('Arrow'))checkpoint();});input.oninput=()=>{l[key]=Number(input.value);out.textContent=Number(l[key]).toFixed(step<1?2:0)+unit;if(key==='start'&&l.start+l.length>state.duration)l.length=Math.max(.05,state.duration-l.start);if(key==='length'&&l.start+l.length>state.duration)l.start=Math.max(0,state.duration-l.length);changeDone();};input.onchange=()=>{if(key==='start'||key==='length')renderProperties();};row.append(lab,input);container.append(row);}
function renderProperties(){let root=$('#properties');root.replaceChildren();const l=current();$('#selectedName').textContent=l?l.name:'Layer properties';if(!l){root.append(el('p','empty','เลือกหรือเพิ่มเลเยอร์'));return;}
 const nameRow=el('div','prop'),nameLabel=el('label','','ชื่อเลเยอร์'),nameInput=el('input');nameInput.type='text';nameInput.value=l.name;nameInput.maxLength=60;nameInput.setAttribute('aria-label','ชื่อเลเยอร์');nameInput.style.width='100%';nameInput.onfocus=()=>checkpoint();nameInput.onchange=()=>{l.name=nameInput.value.trim()||PARTS.find(p=>p.type===l.type).name;refresh();};nameRow.append(nameLabel,nameInput);root.append(nameRow);
 for(const[key,label]of[['color','สีหลัก'],['accent','สีไฮไลต์']]){let row=el('div','prop'),lab=el('label','',label),field=el('div','color-field'),input=el('input');input.type='color';input.value=l[key];input.setAttribute('aria-label',label);let val=el('span','',l[key].toUpperCase());input.onfocus=()=>checkpoint();input.oninput=()=>{l[key]=input.value;val.textContent=l[key].toUpperCase();persist();renderLayers();};field.append(input,val,el('span','','HEX'));row.append(lab,field);root.append(row);}
 range(root,l,'size','ขนาด',.15,2,.01,'×');range(root,l,'opacity','ความเข้ม',0,1,.01);range(root,l,'rotation','การหมุน',-180,180,1,'°');let pos=el('div','prop-row');range(pos,l,'x','ตำแหน่ง X',-1,1,.01);range(pos,l,'y','ตำแหน่ง Y',-1,1,.01);root.append(pos);range(root,l,'speed','ความเร็ว',.1,3,.05,'×');range(root,l,'density','จำนวนชิ้นส่วน',3,80,1);let timing=el('div','prop-row');range(timing,l,'start','เริ่มที่',0,state.duration-.05,.05,' s');range(timing,l,'length','ระยะเวลา',.05,state.duration,.05,' s');root.append(timing);
 let blendRow=el('div','prop'),blendLabel=el('label','','การผสมสี'),blend=el('select');blend.setAttribute('aria-label','การผสมสี');for(const[v,n]of[['lighter','Additive · เรืองแสง'],['source-over','Alpha · สีปกติ']]){let o=el('option','',n);o.value=v;blend.append(o);}blend.value=l.blend;blend.onchange=()=>{checkpoint();l.blend=blend.value;persist();};blendRow.append(blendLabel,blend);root.append(blendRow);
 let seedRow=el('div','prop'),seedLabel=el('label','','Random seed'),seedInput=el('input');seedInput.type='number';seedInput.value=l.seed;seedInput.min=0;seedInput.max=999999;seedInput.setAttribute('aria-label','Random seed');seedInput.onchange=()=>{checkpoint();l.seed=Math.max(0,Math.min(999999,Number(seedInput.value)||0));refresh();};seedRow.append(seedLabel,seedInput);root.append(seedRow);
}
function renderTimeline(){$('#ruler').replaceChildren(...Array.from({length:5},(_,i)=>el('span','',(state.duration*i/4).toFixed(1)+'s')));const list=$('#timelineTracks');list.replaceChildren();[...state.layers].reverse().forEach(l=>{const row=el('div','track'),rail=el('div','track-rail'),bar=el('div','track-bar',l.name);bar.style.left=l.start/state.duration*100+'%';bar.style.width=l.length/state.duration*100+'%';rail.append(bar);row.append(el('span','track-name',l.name),rail);list.append(row);});}
function resize(rect=canvas.getBoundingClientRect()){
 cssWidth=Math.max(1,rect.width);
 // Bound preview work independently of display DPR; exports use their selected resolution.
 const scale=Math.min(1,960/Math.max(1,rect.width,rect.height)),w=Math.max(1,Math.round(rect.width*scale)),h=Math.max(1,Math.round(rect.height*scale));
 if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;gridKey='';invalidate();}
}
new ResizeObserver(entries=>resize(entries[0].contentRect)).observe(canvas);
function drawBackground(){
 const w=canvas.width,h=canvas.height,key=[w,h,bg,showGrid,cssWidth].join(':');
 if(key!==gridKey){gridCanvas.width=w;gridCanvas.height=h;gridCtx.fillStyle=['#0c0d12','#272932','#d2d2d8'][bg];gridCtx.fillRect(0,0,w,h);
  if(showGrid){const size=32*w/cssWidth;gridCtx.strokeStyle=bg===2?'#bfc0c8':'#1c1e28';gridCtx.lineWidth=1;gridCtx.beginPath();for(let x=w/2%size;x<w;x+=size){gridCtx.moveTo(x,0);gridCtx.lineTo(x,h);}for(let y=h/2%size;y<h;y+=size){gridCtx.moveTo(0,y);gridCtx.lineTo(w,y);}gridCtx.stroke();gridCtx.strokeStyle=bg===2?'#a6a3b0':'#35303e';gridCtx.beginPath();gridCtx.moveTo(w/2,0);gridCtx.lineTo(w/2,h);gridCtx.moveTo(0,h/2);gridCtx.lineTo(w,h/2);gridCtx.stroke();}gridKey=key;
 }ctx.drawImage(gridCanvas,0,0);
}
function draw(stamp){
 renderPending=false;
 if(document.hidden||$('#exportDialog').open||$('#helpDialog').open){lastStamp=0;return;}
 if(playing){renderPending=true;requestAnimationFrame(draw);}
 if(!dirty&&(!playing||stamp-lastFrame<1000/30-1))return;
 if(lastStamp&&playing)time=(time+Math.min((stamp-lastStamp)/1000,.25))%state.duration;
 lastStamp=playing?stamp:0;lastFrame=stamp;dirty=false;
 drawBackground();ctx.save();ctx.translate(canvas.width/2,canvas.height/2);const scale=Math.min(canvas.width,canvas.height)/512*zoom;ctx.scale(scale,scale);
 for(const l of state.layers)renderLayer(ctx,l,time,state.duration,previewOptions);ctx.restore();
 if(stamp-lastUI>=100||!playing){timeText.nodeValue=time.toFixed(2)+' ';const total='/ '+state.duration.toFixed(2)+' s';if(durationText.textContent!==total)durationText.textContent=total;scrub.value=time;lastUI=stamp;}
 if(!playing)fpsLabel.textContent='PAUSED';fpsFrames++;if(stamp-fpsStart>=500){fpsLabel.textContent=playing?Math.round(fpsFrames*1000/(stamp-fpsStart))+' FPS':'PAUSED';fpsFrames=0;fpsStart=stamp;}
}
import{renderLayer}from './engine.js?perf=2';
function togglePlay(){playing=!playing;$('#play').textContent=playing?'Ⅱ':'▶';$('#play').title=playing?'หยุด':'เล่น';}
$('#play').onclick=togglePlay;$('#restart').onclick=()=>time=0;$('#step').onclick=()=>{if(playing)togglePlay();time=(time+1/30)%state.duration;};$('#scrub').oninput=e=>{if(playing)togglePlay();time=Number(e.target.value);};$('#duration').onchange=e=>{checkpoint();const old=state.duration;state.duration=Number(e.target.value);state.layers.forEach(l=>{l.start=l.start/old*state.duration;l.length=l.length/old*state.duration;});time=0;refresh();};
$('#grid').onclick=()=>{showGrid=!showGrid;$('#grid').classList.toggle('active',showGrid);};$('#background').onclick=()=>bg=(bg+1)%3;function updateZoom(){zoom=Math.max(.4,Math.min(2,zoom));$('#zoomLabel').textContent=Math.round(zoom*100)+'%';}$('#zoomIn').onclick=()=>{zoom+=.1;updateZoom();};$('#zoomOut').onclick=()=>{zoom-=.1;updateZoom();};$('#resetView').onclick=()=>{zoom=1;updateZoom();};
$$('[data-library]').forEach(b=>b.onclick=()=>{libraryTab=b.dataset.library;$$('[data-library]').forEach(x=>x.classList.toggle('active',x===b));renderLibrary();});$('#search').oninput=renderLibrary;$('#addLayer').onclick=()=>{$('[data-library="parts"]').click();$('#search').value='';renderLibrary();};
$('#duplicate').onclick=()=>{const l=current();if(!l)return;if(state.layers.length>=12)return toast('รองรับสูงสุด 12 เลเยอร์');checkpoint();let n={...l,id:crypto.randomUUID(),name:l.name+' copy'};state.layers.splice(state.layers.indexOf(l)+1,0,n);selected=n.id;refresh();};$('#delete').onclick=()=>{if(!current())return;checkpoint();state.layers=state.layers.filter(l=>l.id!==selected);refresh();};for(const[id,dir]of[['moveUp',1],['moveDown',-1]])$('#'+id).onclick=()=>{let i=state.layers.findIndex(l=>l.id===selected),j=i+dir;if(i<0||j<0||j>=state.layers.length)return;checkpoint();[state.layers[i],state.layers[j]]=[state.layers[j],state.layers[i]];refresh();};
THEMES.forEach(([name,c,a])=>{let b=el('button','palette');b.title=name;b.setAttribute('aria-label','ธีม '+name);let s=el('span');s.style.background=`linear-gradient(135deg,${a},${c})`;b.append(s);b.onclick=()=>{checkpoint();for(let l of state.layers){l.color=c;l.accent=a;}refresh();toast('ใช้ธีม '+name);};$('#palettes').append(b);});
export function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function saveProject(){downloadBlob(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),slug()+'.vfxforge.json');toast('บันทึกโปรเจกต์แล้ว');}function slug(){return state.name.toLowerCase().replace(/[^a-z0-9ก-๙_-]+/g,'-').replace(/^-|-$/g,'')||'vfx-effect';}
$('#save').onclick=saveProject;$('#load').onclick=()=>$('#fileInput').click();
function validateProject(p){if(!p||p.version!==1||typeof p.name!=='string'||p.name.length>100||!Array.isArray(p.layers)||p.layers.length>12||!Number.isFinite(p.duration)||p.duration<.1||p.duration>4)throw Error('รูปแบบโปรเจกต์ไม่ถูกต้อง');const nums={size:[.15,2],opacity:[0,1],rotation:[-180,180],x:[-1,1],y:[-1,1],speed:[.1,3],density:[3,80],seed:[0,999999],start:[0,p.duration],length:[.01,p.duration]};const ids=new Set();for(let l of p.layers){if(!PARTS.some(x=>x.type===l.type)||typeof l.id!=='string'||ids.has(l.id)||typeof l.name!=='string'||l.name.length>100||typeof l.visible!=='boolean'||!['lighter','source-over'].includes(l.blend))throw Error('ข้อมูลเลเยอร์ไม่ถูกต้อง');ids.add(l.id);for(let k of['color','accent'])if(!/^#[0-9a-f]{6}$/i.test(l[k]))throw Error('สีไม่ถูกต้อง');for(let[k,[a,b]]of Object.entries(nums))if(!Number.isFinite(l[k])||l[k]<a||l[k]>b)throw Error('ค่าพารามิเตอร์ไม่ถูกต้อง: '+k);if(l.start+l.length>p.duration+.001)throw Error('เวลาเลเยอร์เกินความยาวโปรเจกต์');}return p;}
$('#fileInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1e6)throw Error('ไฟล์ใหญ่เกิน 1 MB');const p=validateProject(JSON.parse(await f.text()));checkpoint();state=p;time=0;refresh();toast('เปิดโปรเจกต์แล้ว');}catch(err){toast('เปิดไม่ได้: '+err.message);}e.target.value='';};
$('#rename').onclick=()=>{const name=prompt('ชื่อเอฟเฟกต์',state.name);if(name?.trim()){checkpoint();state.name=name.trim().slice(0,100);refresh();}};
$('#help').onclick=()=>$('#helpDialog').showModal();$('#export').onclick=()=>{updateExport();$('#exportDialog').showModal();};$$('[data-format]').forEach(b=>b.onclick=()=>{format=b.dataset.format;$$('[data-format]').forEach(x=>x.classList.toggle('selected',x===b));updateExport();});
function updateExport(){let res=Number($('#resolution').value),n=Number($('#frameCount').value),side=Math.sqrt(n);$('#frameCount').disabled=format==='png';$('#exportNote').textContent={png:'PNG โปร่งใสของเฟรมปัจจุบัน ไม่รวมกริด พื้นหลัง หรือการซูมของพรีวิว',sheet:'PNG atlas โปร่งใส เรียงเฟรมซ้ายไปขวา บนลงล่าง พร้อม JSON ระบุขนาดและ FPS',shader:'ZIP มี .shadergraph + flipbook PNG + .meta เชื่อมภาพอัตโนมัติ ใช้ Time → Multiply → Flipbook → Sample Texture 2D',vfx:'ZIP มี .vfx จากเทมเพลต Unity + flipbook PNG + .meta พร้อม Flipbook Player วนซ้ำบน particle quad'}[format];$('#exportSummary').textContent=format==='png'?`${res} × ${res} px · เฟรมที่ ${time.toFixed(2)} s`:`${res*side} × ${res*side} px atlas · ${n} frames · ${(n/state.duration).toFixed(1)} FPS`;$('#download').textContent='↓ '+(format==='png'?'ดาวน์โหลด PNG':'ดาวน์โหลด ZIP package');}$('#resolution').onchange=updateExport;$('#frameCount').onchange=updateExport;
$('#download').onclick=async()=>{const b=$('#download');b.disabled=true;b.textContent='กำลังสร้างไฟล์…';try{const p=structuredClone(state),result=await exportEffect(p,{format,resolution:Number($('#resolution').value),frames:Number($('#frameCount').value),time,name:slug(),onProgress:s=>b.textContent=s});downloadBlob(result.blob,result.name);toast('ส่งออกสำเร็จ');$('#exportDialog').close();}catch(e){toast('ส่งออกไม่สำเร็จ: '+e.message);console.error(e);}finally{b.disabled=false;updateExport();}};
document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();togglePlay();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();const from=e.shiftKey?redo:undo,to=e.shiftKey?undo:redo;if(from.length){to.push(JSON.stringify(state));state=JSON.parse(from.pop());time=Math.min(time,state.duration-.001);refresh();}}});
try{const saved=localStorage.getItem('vfx-forge-project');if(saved)state=validateProject(JSON.parse(saved));}catch{toast('เริ่มโปรเจกต์ใหม่ เนื่องจากข้อมูลเดิมอ่านไม่ได้');}refresh();renderLibrary();resize();invalidate();
